import React, { useState } from 'react';
import { Tag, Share2, Copy, Check } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Canlı Hayvan Satış & Pazar Yeri İlan Kartı
 * Sahibinden, sosyal medya ve WhatsApp hayvan pazarı grupları için profesyonel ilan künyesi üretir.
 */

export default function MarketplaceCardModal({ isOpen, onClose, animal = {} }) {
  const [price, setPrice] = useState('95000');
  const [sellerPhone, setSellerPhone] = useState('0532 000 00 00');
  const [description, setDescription] = useState('Yüksek süt verimli damızlık gebe düve, tüm karma aşıları tam, resmi TÜRKVET kayıtlı.');
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const adText = `🐮 *SATILIK DAMIZLIK / BESİ HAYVANI İLANI*
🏷️ *Küpe No:* ${animal.code || 'TR16-00482'}
📌 *Adı:* ${animal.name || 'Sarıkız'}
🧬 *Irk / Tür:* ${animal.species || 'Sığır'} — ${animal.breed || 'Siyah Alaca Holstein'}
⚖️ *Canlı Ağırlık:* ${animal.current_weight || 540} kg
♀ *Cinsiyet:* ${animal.gender === 'F' ? 'Dişi' : 'Erkek'}
💉 *Aşı / Sağlık:* Tam, TÜRKVET ve e-Islah sistemine kayıtlı

💰 *Fiyat:* ₺${parseFloat(price).toLocaleString('tr-TR')} (Pazarlık payı vardır)
📍 *Konum:* mFk Farm Tesisleri
📞 *İletişim:* ${sellerPhone}

📝 *Açıklama:* ${description}
_mFk Farm Doğrulanmış Çiftlik Kayıt Belgesi_`;

  const handleCopy = () => {
    navigator.clipboard.writeText(adText);
    setCopied(true);
    toast.success('İlan künyesi panoya kopyalandı!');
    setTimeout(() => setCopied(false), 2500);
  };

  const handleWhatsAppShare = () => {
    const encoded = encodeURIComponent(adText);
    window.open(`https://api.whatsapp.com/send?text=${encoded}`, '_blank');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 bg-black/60 backdrop-blur-xs">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-xl overflow-hidden border border-gray-100">
        <div className="bg-emerald-700 text-white p-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Tag className="w-5 h-5 text-emerald-200" />
            <h3 className="font-bold text-sm">Pazar Yeri İlan Kartı Üretici</h3>
          </div>
          <button onClick={onClose} className="text-white/80 hover:text-white font-bold">✕</button>
        </div>

        <div className="p-4 space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-[11px] font-bold text-gray-600 mb-1">Satış Fiyatı (₺)</label>
              <input
                type="number"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                className="w-full text-xs font-bold border border-gray-200 rounded-lg p-2 bg-gray-50 text-emerald-700"
              />
            </div>
            <div>
              <label className="block text-[11px] font-bold text-gray-600 mb-1">İletişim Telefonu</label>
              <input
                type="text"
                value={sellerPhone}
                onChange={(e) => setSellerPhone(e.target.value)}
                className="w-full text-xs border border-gray-200 rounded-lg p-2"
              />
            </div>
          </div>

          <div>
            <label className="block text-[11px] font-bold text-gray-600 mb-1">İlan Açıklaması</label>
            <textarea
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full text-xs border border-gray-200 rounded-lg p-2 resize-none"
            />
          </div>

          {/* İlan Önizleme Kartı */}
          <div className="bg-gray-50 border border-gray-200 rounded-xl p-3 text-xs font-mono whitespace-pre-line text-gray-800 max-h-48 overflow-y-auto leading-relaxed">
            {adText}
          </div>

          <div className="flex items-center gap-2 pt-2 border-t">
            <button
              onClick={handleCopy}
              className="btn-secondary flex-1 text-xs py-2 px-3 flex items-center justify-center gap-1.5 font-bold"
            >
              {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
              {copied ? 'Kopyalandı' : 'Kopyala'}
            </button>

            <button
              onClick={handleWhatsAppShare}
              className="btn-primary flex-1 text-xs py-2 px-3 flex items-center justify-center gap-1.5 font-bold"
            >
              <Share2 className="w-3.5 h-3.5" />
              Pazarda Paylaş
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
