import React, { useState } from 'react';
import { Activity, Check } from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * Vücut Kondisyon Skoru (BCS 1-5 Skalası)
 * İnek ve küçükbaşlarda yağ rezervlerini (sağrı, omurga, açlık çukurluğu) 1-5 skalasında puanlar.
 */

const BCS_LEVELS = [
  { score: 1.0, label: 'Çok Zayıf', desc: 'Omurga ve kaburgalar aşırı belirgin, deri altında yağ yok.', color: 'bg-red-100 text-red-800 border-red-300' },
  { score: 2.0, label: 'Zayıf', desc: 'Omurga hissedilir, kaburga geçişleri düz, kas rezervi yetersiz.', color: 'bg-orange-100 text-orange-800 border-orange-300' },
  { score: 3.0, label: 'İdeal Sağmal', desc: 'Dengeli yağ örtüsü, omurlar yumuşak hatlı, laktasyon için optimum kondisyon.', color: 'bg-emerald-100 text-emerald-800 border-emerald-300' },
  { score: 4.0, label: 'Yağlı', desc: 'Omurga düz hatlı, kuyruk sokumu yağ tabakası ile kaplı, kuruya alma öncesi dikkat.', color: 'bg-yellow-100 text-yellow-800 border-yellow-300' },
  { score: 5.0, label: 'Aşırı Yağlı / Obez', desc: 'Kemik çıkıntıları kaybolmuş, doğum felci ve ketozis riski çok yüksek.', color: 'bg-red-100 text-red-800 border-red-300' }
];

export default function BcsScoreWidget({ animal, onSaveScore }) {
  const [currentBcs, setCurrentBcs] = useState(3.0);
  const [notes, setNotes] = useState('');

  if (!animal) return null;

  const handleSelectScore = (score) => {
    setCurrentBcs(score);
  };

  const handleSave = () => {
    toast.success(`${animal.name} için BCS ${currentBcs} olarak kaydedildi!`);
    if (onSaveScore) {
      onSaveScore({ bcs: currentBcs, notes, date: new Date().toISOString().split('T')[0] });
    }
  };

  const activeLevel = BCS_LEVELS.find(l => l.score === currentBcs) || BCS_LEVELS[2];

  return (
    <div className="card shadow-sm border border-gray-100 p-4">
      <div className="flex items-center justify-between mb-3 pb-2 border-b">
        <div className="flex items-center gap-2">
          <div className="p-2 bg-emerald-50 text-emerald-700 rounded-xl">
            <Activity className="w-4 h-4" />
          </div>
          <div>
            <h4 className="font-bold text-gray-900 text-xs uppercase tracking-wider">Vücut Kondisyon Skoru (BCS)</h4>
            <p className="text-[11px] text-gray-400">1.0 - 5.0 standart sağrı ve omurga yağ rezervi endeksi</p>
          </div>
        </div>

        <span className={`px-2.5 py-0.5 rounded-full text-xs font-black uppercase ${activeLevel.color}`}>
          Skor: {currentBcs.toFixed(1)} — {activeLevel.label}
        </span>
      </div>

      <p className="text-xs text-gray-600 mb-3 bg-gray-50 p-2.5 rounded-xl border border-gray-100">
        {activeLevel.desc}
      </p>

      {/* 5 Aşamalı Seçim Butonları */}
      <div className="grid grid-cols-5 gap-2 mb-3">
        {BCS_LEVELS.map((level) => (
          <button
            key={level.score}
            type="button"
            onClick={() => handleSelectScore(level.score)}
            className={`py-2 text-center rounded-xl font-black text-xs transition border ${currentBcs === level.score ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm' : 'bg-gray-50 border-gray-200 text-gray-700 hover:bg-gray-100'}`}
          >
            {level.score.toFixed(1)}
          </button>
        ))}
      </div>

      <div className="flex items-center gap-2">
        <input
          type="text"
          placeholder="Gözlem notu (örn. kuruya çıkış öncesi kondisyonu)..."
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          className="flex-1 text-xs border border-gray-200 rounded-xl px-3 py-1.5 bg-gray-50 focus:outline-none focus:ring-1 focus:ring-emerald-500"
        />
        <button
          onClick={handleSave}
          className="btn-primary text-xs py-1.5 px-3 flex items-center gap-1 font-bold shrink-0"
        >
          <Check className="w-3.5 h-3.5" /> Kaydet
        </button>
      </div>
    </div>
  );
}
