import React, { useState } from 'react';
import { Footprints, AlertTriangle, CheckCircle2 } from 'lucide-react';

/**
 * Ayak & Tırnak Sağlığı — Topallık Skor Kartı (Locomotion Score 1-5)
 * ICAR / DairyCo standart topallık gözlem skalasını dijitalleştirir.
 * Veteriner veya çiftçi her hayvan için 1-5 arası skor girer ve zaman içinde trendi görebilir.
 */

const LOCO_SCORES = [
  {
    score: 1,
    label: 'Normal',
    desc: 'Düz sırt, güçlü adım, tüm bacaklar eşit yüklü.',
    color: 'bg-emerald-100 text-emerald-800 border-emerald-300',
    dot: 'bg-emerald-500',
    icon: '🟢',
  },
  {
    score: 2,
    label: 'Hafif Aksama',
    desc: 'Sırtta hafif eğim, yürürken çok az düzensizlik.',
    color: 'bg-lime-100 text-lime-800 border-lime-300',
    dot: 'bg-lime-500',
    icon: '🟡',
  },
  {
    score: 3,
    label: 'Orta Topallık',
    desc: 'Belirgin sırt kamburluğu, yürüyüşte kesik adımlar.',
    color: 'bg-yellow-100 text-yellow-800 border-yellow-300',
    dot: 'bg-yellow-500',
    icon: '🟠',
  },
  {
    score: 4,
    label: 'Ağır Topallık',
    desc: 'Güçlükle hareket, yem tüketimi azalmış, ağırlık bir bacaktan alınmış.',
    color: 'bg-orange-100 text-orange-800 border-orange-300',
    dot: 'bg-orange-500',
    icon: '🔴',
  },
  {
    score: 5,
    label: 'Şiddetli — Tedavi Zorunlu',
    desc: 'Hareket edemez veya çok nadir hareket eder. Acil veteriner müdahalesi gerekir.',
    color: 'bg-red-100 text-red-800 border-red-300',
    dot: 'bg-red-600',
    icon: '🆘',
  },
];

const FOOT_CONDITIONS = [
  'Çürük Ayak (Foot Rot)',
  'Sole Ülseri',
  'Beyaz Çizgi Hastalığı',
  'Tırnak Deformasyonu',
  'Dijital Dermatit (Morvan Hastalığı)',
  'Diğer',
];

export default function LamenessScoreCard({ animal, onSaveScore }) {
  const [selectedScore, setSelectedScore] = useState(null);
  const [selectedCondition, setSelectedCondition] = useState('');
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  if (!animal) return null;

  const handleSave = async () => {
    if (!selectedScore) return;
    setSaving(true);
    try {
      if (onSaveScore) {
        await onSaveScore({
          animalId: animal.id,
          score: selectedScore,
          condition: selectedCondition,
          notes,
          date: new Date().toISOString().split('T')[0],
        });
      }
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
      setSelectedScore(null);
      setNotes('');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="card shadow-sm border border-gray-100">
      {/* Başlık */}
      <div className="flex items-center gap-2 mb-4 pb-2 border-b">
        <div className="p-2 bg-amber-50 text-amber-700 rounded-xl">
          <Footprints className="w-4 h-4" />
        </div>
        <div>
          <h3 className="font-bold text-gray-900 text-sm">Topallık Skor Kartı (LS 1–5)</h3>
          <p className="text-[11px] text-gray-400">ICAR / DairyCo standart locomotion skoru</p>
        </div>
      </div>

      {/* Skor seçimi */}
      <div className="space-y-2 mb-4">
        {LOCO_SCORES.map(ls => (
          <button
            key={ls.score}
            onClick={() => setSelectedScore(ls.score)}
            className={`w-full flex items-center gap-3 p-3 rounded-xl border-2 text-left transition-all ${
              selectedScore === ls.score
                ? `${ls.color} border-current ring-2 ring-current ring-opacity-30 scale-[1.01]`
                : 'bg-gray-50 border-gray-200 hover:border-gray-300'
            }`}
          >
            <span className="text-lg shrink-0">{ls.icon}</span>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <span className="font-black text-sm">Skor {ls.score}</span>
                <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${ls.color}`}>
                  {ls.label}
                </span>
              </div>
              <p className="text-[10px] text-gray-500 mt-0.5 leading-snug">{ls.desc}</p>
            </div>
          </button>
        ))}
      </div>

      {/* Tanı seçimi */}
      {selectedScore && selectedScore >= 2 && (
        <div className="mb-3">
          <label className="block text-xs font-bold text-gray-700 mb-1.5">Olası Tanı / Ayak Sorunu</label>
          <select
            value={selectedCondition}
            onChange={e => setSelectedCondition(e.target.value)}
            className="w-full text-xs border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-amber-400 focus:outline-none"
          >
            <option value="">— Seçiniz —</option>
            {FOOT_CONDITIONS.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      )}

      {/* Notlar */}
      {selectedScore && (
        <>
          <div className="mb-3">
            <label className="block text-xs font-bold text-gray-700 mb-1.5">Veteriner Notu (isteğe bağlı)</label>
            <textarea
              value={notes}
              onChange={e => setNotes(e.target.value)}
              placeholder="Gözlem veya tedavi detayı..."
              rows={2}
              className="w-full text-xs border border-gray-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-amber-400 focus:outline-none resize-none"
            />
          </div>

          {saved ? (
            <div className="flex items-center gap-2 text-emerald-700 text-xs font-bold py-2">
              <CheckCircle2 className="w-4 h-4" /> Topallık skoru kaydedildi!
            </div>
          ) : (
            <button
              onClick={handleSave}
              disabled={saving}
              className="w-full btn-primary text-sm py-2 disabled:opacity-50"
            >
              {saving ? 'Kaydediliyor...' : `Skor ${selectedScore} — ${LOCO_SCORES[selectedScore - 1]?.label} Kaydet`}
            </button>
          )}
        </>
      )}

      {/* Uyarı */}
      {selectedScore >= 4 && (
        <div className="mt-3 flex items-start gap-2 text-[10px] p-2.5 rounded-lg bg-red-50 border border-red-200 text-red-700">
          <AlertTriangle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
          <span>Skor {selectedScore}: Derhal veteriner muayenesi ve tırnak bakımı gereklidir. Süt verimi ve döl verimi ciddi etkilenebilir.</span>
        </div>
      )}
    </div>
  );
}
